package com.Basics;

public class RelationalOperator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 100;
		int b = 29;
		System.out.println(10 > 20);
		System.out.println(a % b > 0);
		System.out.println(b != a );
		
		// < , > , <= , >= , == , !=  
	}

}
